UPDATE andon_record
SET status = #{status}
, handler = #{handler}
, confirm_time = #{confirmTime}
, resolve_time = #{resolveTime}
, resolve_desc = #{resolveDesc}
, duration = #{duration}
WHERE id = #{id} AND is_deleted = 0

mapper.select:
SELECT 
FROM andon_record
WHERE is_deleted = 0

    AND (description LIKE CONCAT('%', #{keyword}, '%')
         OR work_center LIKE CONCAT('%', #{keyword}, '%')
         OR equipment_id LIKE CONCAT('%', #{keyword}, '%')
         OR work_order_id LIKE CONCAT('%', #{keyword}, '%'))


    AND andon_type_id = #{andonTypeId}


    AND status = #{status}


    AND work_center = #{workCenter}


    AND report_time >= #{startTime}


    AND report_time <= #{endTime}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM andon_record
WHERE is_deleted = 0

    AND (description LIKE CONCAT('%', #{keyword}, '%')
         OR work_center LIKE CONCAT('%', #{keyword}, '%')
         OR equipment_id LIKE CONCAT('%', #{keyword}, '%')
         OR work_order_id LIKE CONCAT('%', #{keyword}, '%'))


    AND andon_type_id = #{andonTypeId}


    AND status = #{status}


    AND work_center = #{workCenter}


    AND report_time >= #{startTime}


    AND report_time <= #{endTime}
